// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 deposit1, uint256 deposit2, address user) public {
        vm.assume(user != address(0) && user != address(c));
        deposit1 = bound(deposit1, 0, type(uint256).max / 2);
        deposit2 = bound(deposit2, 0, type(uint256).max / 2);

        vm.deal(user, deposit1 + deposit2);

        vm.startPrank(user);
        c.addToBalance{value: deposit1}();
        c.addToBalance{value: deposit2}();
        vm.stopPrank();

        uint256 balanceOnBook = c.getBalance(user);
        uint256 totalReceived = deposit1 + deposit2;
        assertTrue(balanceOnBook == totalReceived);
    }
}
